public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        long s = 0;
        for (int i = 1; i <= n; i++) {
            s = s + i;
        }
        System.out.println(s);
    }
}

